import React, { useState, useEffect } from "react";
import {
  DashboardIcon,
  UsersIcon,
  TasksIcon,
  MetricsIcon,
  SettingsIcon,
  CloseIcon,
} from "./Icons";

interface SidebarProps {
  isOpen: boolean;
  isCollapsed: boolean;
  onToggle: () => void;
  onCollapse: () => void;
  currentView: string;
  onViewChange: (view: string) => void;
}

const menuItems = [
  {
    id: "dashboard",
    name: "Dashboard",
    icon: DashboardIcon,
  },
  {
    id: "clients",
    name: "Clients",
    icon: UsersIcon,
  },
  {
    id: "tasks",
    name: "Tasks",
    icon: TasksIcon,
  },
  {
    id: "metrics",
    name: "Metrics",
    icon: MetricsIcon,
  },
  {
    id: "settings",
    name: "Settings",
    icon: SettingsIcon,
  },
];

export const Sidebar: React.FC<SidebarProps> = ({
  isOpen,
  isCollapsed,
  onToggle,
  onCollapse,
  currentView,
  onViewChange,
}) => {
  const [systemStatus, setSystemStatus] = useState({
    status: "operational" as "operational" | "warning" | "error",
    message: "All systems operational",
    color: "bg-green-500",
    bgColor: "bg-green-100",
  });

  // Простий статус без автоматичного перемикання
  useEffect(() => {
    // Можна додати реальну логіку перевірки статусу тут
    const currentStatus = {
      status: "operational" as const,
      message: "All systems operational",
      color: "bg-green-500",
      bgColor: "bg-green-100",
    };
    setSystemStatus(currentStatus);
  }, []);

  const renderSystemStatus = () => (
    <div className="group relative bg-white rounded-lg border border-secondary-200 shadow-sm transition-all duration-200 overflow-hidden">
      <div
        className={`flex items-center ${isCollapsed ? "p-3 justify-center" : "p-4"}`}
      >
        {/* Статус індикатор */}
        <div className={`w-3 h-3 bg-success-500 rounded-full ${isCollapsed ? "" : "mr-3"}`}></div>

        {/* Текстова інформація - тільки коли відкритий */}
        {!isCollapsed && (
          <div className="min-w-0 flex-1">
            <p className="text-xs font-medium text-secondary-900 truncate">
              System Status
            </p>
            <p className="text-xs text-secondary-500 truncate">
              {systemStatus.message}
            </p>
          </div>
        )}
      </div>

      {/* Tooltip для згорнутого стану */}
      {isCollapsed && (
        <div className="absolute left-full ml-3 top-1/2 transform -translate-y-1/2 bg-secondary-900 text-white text-xs rounded-md px-3 py-2 opacity-0 group-hover:opacity-100 transition-opacity duration-200 pointer-events-none z-50 whitespace-nowrap shadow-lg">
          System Status: {systemStatus.message}
        </div>
      )}
    </div>
  );

  return (
    <>
      {/* Desktop Sidebar */}
      <div
        className={`hidden lg:flex lg:flex-col lg:fixed lg:inset-y-0 transition-all duration-300 z-30 ${
          isCollapsed ? "lg:w-20" : "lg:w-64"
        }`}
      >
        <div className="flex flex-col flex-grow bg-white shadow-lg border-r border-secondary-200">
          {/* Logo section */}
          <div
            className={`flex items-center flex-shrink-0 px-4 py-6 border-b border-secondary-100 ${isCollapsed ? "justify-center" : ""}`}
          >
            <div className="flex items-center">
              <div className="flex-shrink-0 w-10 h-10 gradient-primary rounded-lg flex items-center justify-center shadow-md">
                <span className="text-sm font-bold text-white">TC</span>
              </div>
              {!isCollapsed && (
                <div className="ml-3 transition-all duration-300">
                  <h2 className="text-base font-semibold text-secondary-900">
                    TetraCore
                  </h2>
                  <p className="text-xs text-secondary-500">StreamHub</p>
                </div>
              )}
            </div>
          </div>

          {/* Navigation */}
          <nav className="flex-1 px-3 py-6 space-y-2">
            {menuItems.map((item) => {
              const isActive = currentView === item.id;
              const IconComponent = item.icon;

              return (
                <div key={item.id} className="relative group">
                  <button
                    onClick={() => onViewChange(item.id)}
                    className={`w-full flex items-center text-sm font-medium rounded-lg transition-all duration-200 relative ${
                      isActive
                        ? "bg-primary-500 text-white shadow-md"
                        : "text-secondary-600 hover:bg-secondary-100 hover:text-secondary-900"
                    } ${isCollapsed ? "px-3 py-3 justify-center" : "px-3 py-3"}`}
                  >
                    <div className={`flex-shrink-0 transition-all duration-200 ${isActive ? "text-white" : "text-secondary-500"} ${isCollapsed ? "" : "mr-3"}`}>
                      <IconComponent size="lg" />
                    </div>
                    {!isCollapsed && (
                      <span className="transition-all duration-300">
                        {item.name}
                      </span>
                    )}
                  </button>

                  {/* Tooltip для згорнутого стану */}
                  {isCollapsed && (
                    <div className="absolute left-full ml-3 top-1/2 transform -translate-y-1/2 bg-secondary-900 text-white text-sm rounded-md px-3 py-2 opacity-0 group-hover:opacity-100 transition-opacity duration-200 pointer-events-none z-50 whitespace-nowrap shadow-lg">
                      {item.name}
                    </div>
                  )}
                </div>
              );
            })}
          </nav>

          {/* Footer */}
          <div className="flex-shrink-0 p-4 border-t border-secondary-100">
            {renderSystemStatus()}
          </div>
        </div>
      </div>

      {/* Mobile Sidebar */}
      <div
        className={`lg:hidden fixed inset-0 z-50 transition-transform duration-300 ${
          isOpen ? "translate-x-0" : "-translate-x-full"
        }`}
      >
        <div className="flex">
          {/* Sidebar content */}
          <div className="flex flex-col w-64 bg-white shadow-xl">
            {/* Logo section */}
            <div className="flex items-center justify-between flex-shrink-0 px-4 py-4 border-b border-secondary-200">
              <div className="flex items-center">
                <div className="flex-shrink-0 w-8 h-8 gradient-primary rounded-lg flex items-center justify-center shadow-md">
                  <span className="text-sm font-bold text-white">TC</span>
                </div>
                <div className="ml-3">
                  <h2 className="text-sm font-semibold text-secondary-900">
                    TetraCore
                  </h2>
                  <p className="text-xs text-secondary-500">StreamHub</p>
                </div>
              </div>
              <button
                onClick={onToggle}
                className="p-2 text-secondary-400 hover:text-secondary-500 hover:bg-secondary-100 rounded-lg transition-colors duration-200"
              >
                <CloseIcon size="lg" />
              </button>
            </div>

            {/* Navigation */}
            <nav className="flex-1 px-3 py-4 space-y-1">
              {menuItems.map((item) => {
                const isActive = currentView === item.id;
                const IconComponent = item.icon;

                return (
                  <button
                    key={item.id}
                    onClick={() => {
                      onViewChange(item.id);
                      onToggle(); // Close mobile sidebar after selection
                    }}
                    className={`group flex items-center w-full px-3 py-3 text-sm font-medium rounded-lg transition-all duration-200 ${
                      isActive
                        ? "bg-primary-500 text-white shadow-md"
                        : "text-secondary-600 hover:bg-secondary-100 hover:text-secondary-900"
                    }`}
                  >
                    <div className={`flex-shrink-0 mr-3 transition-all duration-200 ${isActive ? "text-white" : "text-secondary-500"}`}>
                      <IconComponent size="lg" />
                    </div>
                    <span>{item.name}</span>
                  </button>
                );
              })}
            </nav>

            {/* Footer */}
            <div className="flex-shrink-0 p-4 border-t border-secondary-200">
              {renderSystemStatus()}
            </div>
          </div>
        </div>
      </div>
    </>
  );
};
